async function runBoundedDiagnostic(args) {
	let timer;
	try {
		const timedOut = Symbol("diagnostic-timeout");
		const deadline = new Promise((resolve) => {
			timer = setTimeout(() => resolve(timedOut), args.timeoutMs);
			timer.unref?.();
		});
		if (await Promise.race([args.run(), deadline]) === timedOut) args.logger.debug?.(args.timedOutMessage);
	} catch (error) {
		args.logger.debug?.(`${args.failedMessagePrefix}${error instanceof Error ? error.message : String(error)}`);
	} finally {
		if (timer) clearTimeout(timer);
	}
}
